(() => {
 'use strict';
 const data=EXAM2_GAP_FILL,E=EXAM2_CONTENT;
 for(const {after,...lesson} of data.lessons){
  const at=E.lessons.findIndex(l=>l.id===after);if(at<0)throw Error('Unknown anchor lesson '+after);
  E.lessons.splice(at+1,0,{...lesson,kind:'combined',chapter:{'Emotion & motivation':'7','Memory II':'9','Learning I':'8','Learning II':'8'}[lesson.unit],examEligible:true,questions:[]});
 }
 for(const [id,list] of Object.entries(data.questions)){
  const lesson=E.lessons.find(l=>l.id===id);if(!lesson)throw Error('Unknown lesson '+id);
  list.forEach((q,i)=>lesson.questions.push({...q,id:id+'-gap'+i}));
 }
 for(const r of data.review){
  const topic=E.review.topics.find(t=>t.prompt.includes(r.match));if(!topic)throw Error('Unknown review prompt '+r.match);
  topic.lessonIds=[...new Set([...topic.lessonIds,...r.lessons])];topic.status=r.status;if(r.note)topic.note=r.note;
 }
})();
